import{_ as s,o as e,c as t,a3 as n}from"./chunks/framework.BlfGB29P.js";const b=JSON.parse('{"title":"架构与实战组装配方与能力自检","description":"把架构决策、项目路径与交付六件套收成配方 A–E，给出 AI 客服中心基线与 P2–P5 四种产品形态的决策表与跨组自检清单。","frontmatter":{"title":"架构与实战组装配方与能力自检","description":"把架构决策、项目路径与交付六件套收成配方 A–E，给出 AI 客服中心基线与 P2–P5 四种产品形态的决策表与跨组自检清单。","outline":[2,3],"article":{"type":"index","structure":"index"}},"headers":[],"relativePath":"ts-ai/architecture/assembly/assembly-recipes-checklist.md","filePath":"ts-ai/architecture/assembly/assembly-recipes-checklist.md","lastUpdated":1786166505000}'),r={name:"ts-ai/architecture/assembly/assembly-recipes-checklist.md"};function i(l,a,p,d,c,o){return e(),t("div",null,[...a[0]||(a[0]=[n(`<h1 id="架构与实战组装配方与能力自检" tabindex="-1">架构与实战组装配方与能力自检 <a class="header-anchor" href="#架构与实战组装配方与能力自检" aria-label="Permalink to &quot;架构与实战组装配方与能力自检&quot;">​</a></h1><blockquote><p>作者：cursor-grok-4.5</p></blockquote><p>设计决策、Agent 类型、项目实战、项目交付各组偏专题。本篇不重抄分层图或项目步骤，只回答：<strong>要组装成哪种「可交接」结果、抄哪条项目路径、离开本模块前还缺什么。</strong></p><p>服务端见 <a href="/ts-ai/backend/assembly/assembly-recipes-checklist">AI 服务组装配方</a>；前端见 <a href="/ts-ai/integration/assembly/assembly-recipes-checklist">全栈集成组装配方</a>；知识侧见 <a href="/ts-ai/knowledge/assembly/assembly-recipes-checklist">RAG 与记忆组装配方</a>；上线横切见 <a href="/ts-ai/quality/assembly/assembly-recipes-checklist">质量与生产组装配方</a>。本篇站在 <strong>架构决策 + 贯穿项目 + 交付文档</strong> 视角。</p><p><strong>P1 基线完成后，P2–P4 是三种独立产品形态，一次选一个做</strong>（各自从 P1 基线成品起步）；不要多线并行。P5 是可选进阶，不是默认主路径。完整规划见 <a href="/ts-ai/architecture/">架构与实战总览 §后续项目实战规划</a>。</p><h2 id="_1-你要组装的结果形态" tabindex="-1">1. 你要组装的结果形态 <a class="header-anchor" href="#_1-你要组装的结果形态" aria-label="Permalink to &quot;1. 你要组装的结果形态&quot;">​</a></h2><h3 id="_1-1-可辩护的架构决策集" tabindex="-1">1.1 可辩护的架构决策集 <a class="header-anchor" href="#_1-1-可辩护的架构决策集" aria-label="Permalink to &quot;1.1 可辩护的架构决策集&quot;">​</a></h3><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>分层图（交互 / 应用 / Agent / 工作流 / 数据 / 基础设施）</span></span>
<span class="line"><span>  → 框架边界：Nuxt / Nest / LangChain / LangGraph 依赖方向</span></span>
<span class="line"><span>  → 状态所有权：UI 临时态 vs 服务端事实 vs Run vs 持久数据</span></span>
<span class="line"><span>  →（按需）模型网关 ADR、选型 ADR</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>读完应能向评审说明「为什么这样切、状态归谁、什么进图什么不进」。入口：<a href="/ts-ai/architecture/design-decisions/ts-ai-fullstack-architecture">TS-AI 全栈分层架构</a> → <a href="/ts-ai/architecture/design-decisions/framework-boundaries">框架边界</a> → <a href="/ts-ai/architecture/design-decisions/frontend-backend-state-ownership">前后端状态所有权</a>。</p><h3 id="_1-2-可启动的全栈路径-基线或升级版" tabindex="-1">1.2 可启动的全栈路径（基线或升级版） <a class="header-anchor" href="#_1-2-可启动的全栈路径-基线或升级版" aria-label="Permalink to &quot;1.2 可启动的全栈路径（基线或升级版）&quot;">​</a></h3><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>共用底座：Nuxt + Nest + LangChain.js + Postgres Thread/Run + 自建 SSE</span></span>
<span class="line"><span>  → 配方 A：AI 客服中心（证协议，必修基线）</span></span>
<span class="line"><span>  → 三种产品形态（一次一个，正文待写）：</span></span>
<span class="line"><span>       ├─ 配方 B：产品帮助中心问答（P2，对外 RAG）</span></span>
<span class="line"><span>       ├─ 配方 C：深度研究报告（P3，异步长任务）</span></span>
<span class="line"><span>       └─ 配方 D：经营数据分析（P4，MCP 治理落产品）</span></span>
<span class="line"><span>  →（可选进阶）配方 E：多角色内容审校流水线（P5）</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p>项目地图见 <a href="/ts-ai/architecture/ai-customer-support/">实战 · AI 客服中心</a>。目标是<strong>一条可演示、可验收的主路径</strong>，不是所有配方都做完。</p><h3 id="_1-3-可交接的交付六件套" tabindex="-1">1.3 可交接的交付六件套 <a class="header-anchor" href="#_1-3-可交接的交付六件套" aria-label="Permalink to &quot;1.3 可交接的交付六件套&quot;">​</a></h3><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>需求与验收 → 评测方案 → 数据与权限</span></span>
<span class="line"><span>  → 威胁模型 → 发布清单 → 运维交接</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>方法在 <a href="/ts-ai/quality/">质量与生产</a>；空白表在 <a href="/ts-ai/appendix/templates/">附录·工程模板</a>。本模块填<strong>本项目具体值</strong>。入口：<a href="/ts-ai/architecture/delivery/">项目交付</a>。没有六件套的「能跑 Demo」不算模块完成。</p><p>建议路径（与 <a href="/ts-ai/architecture/">架构与实战总览</a> 一致）：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>AI 客服中心（必修基线，最小可交付）</span></span>
<span class="line"><span>  ├─→ P2 产品帮助中心问答（对外 RAG + 反馈闭环）</span></span>
<span class="line"><span>  ├─→ P3 深度研究报告（长任务 / Interrupt / 检查点）</span></span>
<span class="line"><span>  ├─→ P4 经营数据分析（NL→SQL→图表 + MCP 治理）</span></span>
<span class="line"><span>  └─→（可选）P5 多角色内容审校流水线</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><h2 id="_2-能力拼装图" tabindex="-1">2. 能力拼装图 <a class="header-anchor" href="#_2-能力拼装图" aria-label="Permalink to &quot;2. 能力拼装图&quot;">​</a></h2><h3 id="_2-1-决策必备件" tabindex="-1">2.1 决策必备件 <a class="header-anchor" href="#_2-1-决策必备件" aria-label="Permalink to &quot;2.1 决策必备件&quot;">​</a></h3><table tabindex="0"><thead><tr><th>必备件</th><th>去哪查</th></tr></thead><tbody><tr><td>全栈分层与依赖方向</td><td><a href="/ts-ai/architecture/design-decisions/ts-ai-fullstack-architecture">分层架构</a>、<a href="/ts-ai/architecture/design-decisions/framework-boundaries">框架边界</a></td></tr><tr><td>UI / Run / 持久状态归谁</td><td><a href="/ts-ai/architecture/design-decisions/frontend-backend-state-ownership">前后端状态所有权</a></td></tr><tr><td>网关位置与可替换策略（按需）</td><td><a href="/ts-ai/architecture/design-decisions/model-gateway">模型网关</a></td></tr><tr><td>选型记录与复查条件（按需）</td><td><a href="/ts-ai/architecture/design-decisions/framework-selection-adr">框架选型与 ADR</a></td></tr><tr><td>Research / SQL 等模式约束（按需）</td><td><a href="/ts-ai/architecture/agent-types/">Agent 类型</a></td></tr><tr><td>交付六件套条目</td><td><a href="/ts-ai/architecture/delivery/">项目交付</a></td></tr></tbody></table><p>必学顺序：决策前三篇 → 选 0～1 篇 Agent 类型（不要通读）→ 一条项目路径 → 边做边填交付。</p><h3 id="_2-2-项目与模块接缝" tabindex="-1">2.2 项目与模块接缝 <a class="header-anchor" href="#_2-2-项目与模块接缝" aria-label="Permalink to &quot;2.2 项目与模块接缝&quot;">​</a></h3><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>架构决策（必学前三篇）</span></span>
<span class="line"><span>  → AI 客服中心：backend Run/SSE + integration Chat</span></span>
<span class="line"><span>  → P2 帮助中心问答：+ knowledge Ingestion / 检索 / 引用 / 反馈闭环</span></span>
<span class="line"><span>  → P3 研究报告：+ workflow 长任务 / Interrupt / 检查点</span></span>
<span class="line"><span>  → P4 数据分析：+ MCP 治理 / NL→SQL / 护栏</span></span>
<span class="line"><span>  → P5（可选进阶）内容审校：+ Supervisor / 预算守卫</span></span>
<span class="line"><span>  → 交付六件套 → quality 门禁与发布</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><table tabindex="0"><thead><tr><th>项目 / 增量</th><th>相对共用底座多什么</th><th>主文</th></tr></thead><tbody><tr><td>AI 客服中心（必修基线）</td><td>Thread/Run、Nest SSE、取消重连、租户鉴权、Gateway、分诊建工单、Nuxt Chat</td><td><a href="/ts-ai/architecture/ai-customer-support/">实战 · AI 客服中心</a></td></tr><tr><td>帮助中心问答（P2，正文待写）</td><td>Ingestion、Embedding、pgvector、权限检索、引用、嵌入式组件、反馈闭环</td><td><a href="/ts-ai/knowledge/assembly/assembly-recipes-checklist">RAG 组装配方</a></td></tr><tr><td>研究报告（P3，正文待写）</td><td>长任务队列、Interrupt、检查点恢复、报告引用</td><td><a href="/ts-ai/workflow/">工作流</a></td></tr><tr><td>数据分析（P4，正文待写）</td><td>数据 MCP Server、网关白名单与审计、NL→SQL、只读护栏</td><td><a href="/ts-ai/agent/tools-mcp/">工具与 MCP</a></td></tr><tr><td>内容审校（P5 可选，正文待写）</td><td>Supervisor/Handoff、共享状态、终止与成本、对照实验</td><td><a href="/ts-ai/workflow/multi-agent/">多 Agent</a></td></tr></tbody></table><table tabindex="0"><thead><tr><th>接缝</th><th>别在本篇重做</th></tr></thead><tbody><tr><td>Nest SSE / Thread-Run</td><td><a href="/ts-ai/backend/assembly/assembly-recipes-checklist">服务端组装配方</a></td></tr><tr><td>Chat / 取消重连 / HITL UI</td><td><a href="/ts-ai/integration/assembly/assembly-recipes-checklist">全栈集成组装配方</a></td></tr><tr><td>向量检索 / 引用 / 租户过滤</td><td><a href="/ts-ai/knowledge/assembly/assembly-recipes-checklist">RAG 组装配方</a></td></tr><tr><td>图、Checkpoint、Interrupt</td><td><a href="/ts-ai/workflow/">工作流</a></td></tr><tr><td>MCP 协议与 adapters</td><td><a href="/ts-ai/agent/tools-mcp/">工具与 MCP</a></td></tr><tr><td>Mock / 门禁 / 安全 / 发布</td><td><a href="/ts-ai/quality/assembly/assembly-recipes-checklist">质量组装配方</a></td></tr></tbody></table><p>本模块负责：<strong>选哪条路径、决策是否可辩护、交付文档是否齐</strong>。API 与协议实现仍归对应模块。</p><h2 id="_3-推荐配方" tabindex="-1">3. 推荐配方 <a class="header-anchor" href="#_3-推荐配方" aria-label="Permalink to &quot;3. 推荐配方&quot;">​</a></h2><h3 id="_3-1-配方-a-ai-客服中心-p1-已交付" tabindex="-1">3.1 配方 A：AI 客服中心（P1，已交付） <a class="header-anchor" href="#_3-1-配方-a-ai-客服中心-p1-已交付" aria-label="Permalink to &quot;3.1 配方 A：AI 客服中心（P1，已交付）&quot;">​</a></h3><p><strong>何时用：</strong> 默认起点；要先证明全栈协议与壳可交接，刻意不做重 RAG / 重审批图。</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Thread / Run / Message（Postgres）</span></span>
<span class="line"><span>  → Nest 鉴权租户 + Model Gateway + 最小 Agent</span></span>
<span class="line"><span>  → 自建 SSE：started / delta / completed / cancelled</span></span>
<span class="line"><span>  → Nuxt Chat：流式气泡、取消、重连去重</span></span>
<span class="line"><span>  → 评测门禁底线 + 关联 ID 日志</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>拼：<a href="/ts-ai/architecture/ai-customer-support/">实战 · AI 客服中心</a> + <a href="/ts-ai/architecture/design-decisions/ts-ai-fullstack-architecture">分层架构</a> + <a href="/ts-ai/architecture/design-decisions/frontend-backend-state-ownership">状态所有权</a>。协议与 UI 细节回 <a href="/ts-ai/integration/">integration</a>；Run API 回 <a href="/ts-ai/backend/">backend</a>。</p><p><strong>验收信号：</strong> 登录用户可建 Thread、流式对话、取消与重连语义稳定；跨租户读不到他户 Thread；分诊可建工单与提示转人工；无知识库上传闭环、无审批 Interrupt。交付至少起草需求与威胁模型草稿。</p><h3 id="_3-2-配方-b-基线-→-产品帮助中心问答-p2-对外-rag-正文待写" tabindex="-1">3.2 配方 B：基线 → 产品帮助中心问答（P2，对外 RAG，正文待写） <a class="header-anchor" href="#_3-2-配方-b-基线-→-产品帮助中心问答-p2-对外-rag-正文待写" aria-label="Permalink to &quot;3.2 配方 B：基线 → 产品帮助中心问答（P2，对外 RAG，正文待写）&quot;">​</a></h3><p><strong>何时用：</strong> 主痛点是对外用户「答得准、有依据」，需要反馈闭环；已有或准备完成配方 A 底座。</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>配方 A 底座</span></span>
<span class="line"><span>  → Ingestion / Embedding / pgvector</span></span>
<span class="line"><span>  → 权限过滤检索 + citation</span></span>
<span class="line"><span>  → 嵌入式问答组件 + 管理台（文档 / 索引状态）</span></span>
<span class="line"><span>  → “是否有帮助”反馈回流评测</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>拼：<a href="/ts-ai/knowledge/assembly/assembly-recipes-checklist">RAG 组装配方</a>；项目正文待写。数据权限与租户边界写入 <a href="/ts-ai/architecture/delivery/data-permission-design">数据与权限设计</a>。</p><p><strong>验收信号：</strong> 仅授权文档可召回；回答带引用；空检索不胡答（门禁有负例）；基线协议能力不回退。</p><h3 id="_3-3-配方-c-基线-→-深度研究报告-p3-正文待写" tabindex="-1">3.3 配方 C：基线 → 深度研究报告（P3，正文待写） <a class="header-anchor" href="#_3-3-配方-c-基线-→-深度研究报告-p3-正文待写" aria-label="Permalink to &quot;3.3 配方 C：基线 → 深度研究报告（P3，正文待写）&quot;">​</a></h3><p><strong>何时用：</strong> 主痛点是「异步长任务 + 人机确认 + 可恢复执行」；HITL 用「大纲确认」承载。从 P1 基线起步，不依赖 P2。</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>配方 A 底座</span></span>
<span class="line"><span>  → 研究计划与证据模型</span></span>
<span class="line"><span>  → 任务队列 + 长时 Run + 检查点</span></span>
<span class="line"><span>  → 大纲确认（Interrupt + HITL）</span></span>
<span class="line"><span>  → 报告生成与引用追溯</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>拼：<a href="/ts-ai/workflow/">工作流</a> + <a href="/ts-ai/integration/ai-interaction/tool-confirmation-human-loop">工具确认与人在回路</a>；项目正文待写。威胁与写操作路径写入 <a href="/ts-ai/architecture/delivery/threat-model">威胁模型</a>。</p><p><strong>验收信号：</strong> 大纲确认后才继续生成；中断 / 重启后可恢复同一任务；重放不重复执行；报告引用可追溯。</p><h3 id="_3-4-配方-d-基线-→-经营数据分析-p4-正文待写" tabindex="-1">3.4 配方 D：基线 → 经营数据分析（P4，正文待写） <a class="header-anchor" href="#_3-4-配方-d-基线-→-经营数据分析-p4-正文待写" aria-label="Permalink to &quot;3.4 配方 D：基线 → 经营数据分析（P4，正文待写）&quot;">​</a></h3><p><strong>何时用：</strong> 要让业务用自然语言查数，且 MCP 工具必须<strong>受控</strong>接入（白名单 / 审计 / 超时），而不是 Agent 直连任意 Server。</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>配方 A 底座</span></span>
<span class="line"><span>  → Schema 元数据 + 结构化输出（NL→SQL）</span></span>
<span class="line"><span>  → 数据 MCP Server + Nest 网关治理</span></span>
<span class="line"><span>  → 只读护栏与越权拒绝</span></span>
<span class="line"><span>  → 看板 UI（图表）</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>拼：<a href="/ts-ai/agent/tools-mcp/langchain-mcp-integration">LangChain.js 集成 MCP</a> + <a href="/ts-ai/quality/security-governance/tool-permissions">工具权限</a>；项目正文待写。Server 来源写入 <a href="/ts-ai/quality/security-governance/dependency-supply-chain-security">供应链安全</a>。</p><p><strong>验收信号：</strong> SQL 只读；越权表查不到；结构化输出过校验；幻觉工具名执行层拒绝；调用审计可核对。</p><h3 id="_3-5-配方-e-多角色内容审校流水线-p5-可选进阶-正文待写" tabindex="-1">3.5 配方 E：多角色内容审校流水线（P5 可选进阶，正文待写） <a class="header-anchor" href="#_3-5-配方-e-多角色内容审校流水线-p5-可选进阶-正文待写" aria-label="Permalink to &quot;3.5 配方 E：多角色内容审校流水线（P5 可选进阶，正文待写）&quot;">​</a></h3><p><strong>何时用：</strong> 已有单 Agent 基线（A，或完成 B/C/D 之一），且能证明「拆角色」相对收益（质量 / 成本 / 可维护）。场景是合规审校线（稿件 → 初审 → 复核 → 结论），不是写营销稿。不是默认主路径。</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>单 Agent 或单图基线（A，或 B/C/D 之一）</span></span>
<span class="line"><span>  → Supervisor / Handoff + 共享状态</span></span>
<span class="line"><span>  → 明确终止条件与成本上限</span></span>
<span class="line"><span>  → 对比基线：正确率 / 延迟 / Token 不劣于阈值</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>拼：<a href="/ts-ai/workflow/">workflow</a>；项目正文待写。对照指标写入 <a href="/ts-ai/architecture/delivery/evaluation-plan">评测方案</a>。</p><p><strong>验收信号：</strong> 有基线对照实验；终止与成本有硬上限；失败可归因到角色/边；<strong>禁止</strong>把多角色当学习起点。</p><h2 id="_4-决策表" tabindex="-1">4. 决策表 <a class="header-anchor" href="#_4-决策表" aria-label="Permalink to &quot;4. 决策表&quot;">​</a></h2><h3 id="_4-1-停在基线-vs-下一个产品形态" tabindex="-1">4.1 停在基线 vs 下一个产品形态 <a class="header-anchor" href="#_4-1-停在基线-vs-下一个产品形态" aria-label="Permalink to &quot;4.1 停在基线 vs 下一个产品形态&quot;">​</a></h3><table tabindex="0"><thead><tr><th>条件</th><th>选</th></tr></thead><tbody><tr><td>协议 / 鉴权 / SSE / Chat 尚未稳定</td><td><strong>停在配方 A</strong>，先交客服中心</td></tr><tr><td>下一步想证对外问答：引用 / 拒答 / 反馈闭环</td><td><strong>配方 B</strong>（P2）</td></tr><tr><td>下一步想证异步长任务与人机确认</td><td><strong>配方 C</strong>（P3）</td></tr><tr><td>下一步想证自然语言查数与 MCP 治理</td><td><strong>配方 D</strong>（P4）</td></tr><tr><td>想同时开工 B/C/D</td><td><strong>不推荐</strong>；一次一个，各自独立验收</td></tr><tr><td>还没有 A，直接开 B–D</td><td><strong>不推荐</strong>（协议债会淹没领域验收）</td></tr></tbody></table><h3 id="_4-2-何时上数据分析-mcp-治理-vs-多角色" tabindex="-1">4.2 何时上数据分析（MCP 治理）vs 多角色 <a class="header-anchor" href="#_4-2-何时上数据分析-mcp-治理-vs-多角色" aria-label="Permalink to &quot;4.2 何时上数据分析（MCP 治理）vs 多角色&quot;">​</a></h3><table tabindex="0"><thead><tr><th>条件</th><th>选</th></tr></thead><tbody><tr><td>要接外部工具（尤其数据库）且必须白名单/审计</td><td><strong>配方 D（数据分析）</strong></td></tr><tr><td>本地 <code>tool()</code> 已够用</td><td><strong>不上 D</strong></td></tr><tr><td>审校角色拆分有对照收益</td><td><strong>配方 E（内容审校）</strong></td></tr><tr><td>「感觉要多智能体」但无对照</td><td><strong>不升级 E</strong></td></tr><tr><td>把 D/E 当第一课</td><td><strong>禁止</strong></td></tr></tbody></table><h3 id="_4-3-research-sql-类型篇-vs-项目实战承接" tabindex="-1">4.3 Research / SQL：类型篇 vs 项目实战承接 <a class="header-anchor" href="#_4-3-research-sql-类型篇-vs-项目实战承接" aria-label="Permalink to &quot;4.3 Research / SQL：类型篇 vs 项目实战承接&quot;">​</a></h3><table tabindex="0"><thead><tr><th>条件</th><th>选</th></tr></thead><tbody><tr><td>只要理解研究或 SQL Agent 的约束与评测点</td><td>读 <a href="/ts-ai/architecture/agent-types/research-agent">Research Agent</a> / <a href="/ts-ai/architecture/agent-types/data-sql-agent">Data/SQL Agent</a></td></tr><tr><td>想完整做一个研究报告产品</td><td><strong>配方 C</strong>（P3，HITL 用大纲确认承载；与 py-agent 售后领域错开）</td></tr><tr><td>想完整做一个只读 SQL 数据产品</td><td><strong>配方 D</strong>（P4，数据工具走 MCP 受控接入）</td></tr><tr><td>SQL 要直连生产写库</td><td><strong>拒绝</strong>；走沙箱 + 审计模式（见类型篇）</td></tr></tbody></table><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>协议还不稳？           → 配方 A</span></span>
<span class="line"><span>要对外问答 / 引用？     → 配方 B（P2）</span></span>
<span class="line"><span>要长任务 / 人机确认？   → 配方 C（P3）</span></span>
<span class="line"><span>要查数 / 接外部工具？   → 配方 D（P4）</span></span>
<span class="line"><span>基线不够才拆角色？     → 配方 E（P5）</span></span>
<span class="line"><span>纠结选哪个形态？       → §4.1</span></span>
<span class="line"><span>纠结 MCP / 多角色？    → §4.2</span></span>
<span class="line"><span>纠结 Research/SQL？    → §4.3</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><h2 id="_5-能力自检清单" tabindex="-1">5. 能力自检清单 <a class="header-anchor" href="#_5-能力自检清单" aria-label="Permalink to &quot;5. 能力自检清单&quot;">​</a></h2><p>离开 <a href="/ts-ai/architecture/">架构与实战</a> 或进入对外发布准备前勾选。勾不完回 §6。</p><h3 id="_5-1-架构决策自检" tabindex="-1">5.1 架构决策自检 <a class="header-anchor" href="#_5-1-架构决策自检" aria-label="Permalink to &quot;5.1 架构决策自检&quot;">​</a></h3><ul><li>[ ] 能画分层图，并指出 Nuxt / Nest / LangChain / LangGraph 各自不做什么</li><li>[ ] 能说明 UI 临时态、服务端事实、Run、持久数据的所有权边界</li><li>[ ] 依赖方向无「前端直连模型 Key / UI 持有业务事实源」</li><li>[ ] （若启用）网关 ADR 写清位置、统一策略、故障隔离与复查条件</li><li>[ ] Chain / Agent / Workflow 选型与项目形态一致（不为了用图而用图）</li><li>[ ] 能向他人用一页纸讲清：为什么选这条路径、什么明确不做</li></ul><h3 id="_5-2-所选项目路径自检" tabindex="-1">5.2 所选项目路径自检 <a class="header-anchor" href="#_5-2-所选项目路径自检" aria-label="Permalink to &quot;5.2 所选项目路径自检&quot;">​</a></h3><ul><li>[ ] <strong>只选了一条</strong>主路径（A，或 A 后的 B/C/D 之一；E 仅作进阶加码）</li><li>[ ] 配方 A：SSE 事件、取消重连、租户鉴权、Gateway 可演示</li><li>[ ] 配方 B（若选）：权限检索、引用、嵌入式组件、空检索负例、反馈闭环</li><li>[ ] 配方 C（若选）：大纲确认 HITL、长任务队列、检查点恢复、引用可追溯</li><li>[ ] 配方 D（若选）：SQL 只读护栏、白名单、幻觉工具拒绝、审计可查</li><li>[ ] 配方 E（若选）：有相对单 Agent 的对照收益与成本上限</li><li>[ ] 多个产品形态未并行当「双主交付」</li></ul><h3 id="_5-3-项目交付自检" tabindex="-1">5.3 项目交付自检 <a class="header-anchor" href="#_5-3-项目交付自检" aria-label="Permalink to &quot;5.3 项目交付自检&quot;">​</a></h3><ul><li>[ ] <a href="/ts-ai/architecture/delivery/requirements-acceptance">需求与验收</a>：用户、样例、非目标、完成定义已填</li><li>[ ] <a href="/ts-ai/architecture/delivery/evaluation-plan">评测方案</a>：数据集切分、基线、阈值已挂门禁口径</li><li>[ ] <a href="/ts-ai/architecture/delivery/data-permission-design">数据与权限</a>：表/索引/租户边界与项目一致</li><li>[ ] <a href="/ts-ai/architecture/delivery/threat-model">威胁模型</a>：资产、路径、控制、剩余风险已评审</li><li>[ ] <a href="/ts-ai/architecture/delivery/release-checklist">发布清单</a>：当日勾选项可执行</li><li>[ ] <a href="/ts-ai/architecture/delivery/operations-handover">运维交接</a>：SLO、Runbook、演练记录齐</li><li>[ ] 六件套中的方法外链已落到 quality，正文是本项目取值而非百科摘抄</li></ul><h2 id="_6-未通过时的回跳路径" tabindex="-1">6. 未通过时的回跳路径 <a class="header-anchor" href="#_6-未通过时的回跳路径" aria-label="Permalink to &quot;6. 未通过时的回跳路径&quot;">​</a></h2><table tabindex="0"><thead><tr><th>缺口</th><th>回跳</th></tr></thead><tbody><tr><td>分层 / 边界 / 状态说不清</td><td><a href="/ts-ai/architecture/design-decisions/">架构与决策</a> 前三篇</td></tr><tr><td>网关或选型 ADR 空</td><td><a href="/ts-ai/architecture/design-decisions/model-gateway">模型网关</a>、<a href="/ts-ai/architecture/design-decisions/framework-selection-adr">框架选型 ADR</a></td></tr><tr><td>不知选哪条项目线</td><td>§4.1 + <a href="/ts-ai/architecture/">架构与实战总览</a></td></tr><tr><td>基线协议 / Chat 不稳</td><td><a href="/ts-ai/architecture/ai-customer-support/">实战 · AI 客服中心</a> → <a href="/ts-ai/integration/assembly/assembly-recipes-checklist">integration 组装配方</a></td></tr><tr><td>检索 / 引用 / 串租户</td><td>§3.2 + <a href="/ts-ai/knowledge/assembly/assembly-recipes-checklist">RAG 组装配方</a></td></tr><tr><td>审批图 / Interrupt / 幂等</td><td>§3.3 + <a href="/ts-ai/workflow/">workflow</a></td></tr><tr><td>MCP 直连 / 无白名单 / 无审计</td><td>§3.4 + <a href="/ts-ai/agent/tools-mcp/">tools-mcp</a></td></tr><tr><td>多角色无收益证明</td><td>§4.2 + §3.5</td></tr><tr><td>Research / SQL 与项目关系乱</td><td>§4.3 + <a href="/ts-ai/architecture/agent-types/">Agent 类型</a></td></tr><tr><td>交付文档空洞</td><td><a href="/ts-ai/architecture/delivery/">项目交付</a></td></tr><tr><td>门禁 / 安全 / 发布方法不会</td><td><a href="/ts-ai/quality/assembly/assembly-recipes-checklist">质量组装配方</a></td></tr><tr><td>Nest Run / SSE 实现缺口</td><td><a href="/ts-ai/backend/assembly/assembly-recipes-checklist">服务端组装配方</a></td></tr></tbody></table><h2 id="_7-验收标准" tabindex="-1">7. 验收标准 <a class="header-anchor" href="#_7-验收标准" aria-label="Permalink to &quot;7. 验收标准&quot;">​</a></h2><p>能不看目录，根据目标在配方 A–E 中选型；能区分「停在工作台 / 升级知识库 / 升级售后 / 进阶 MCP / 进阶多角色」；能说明 Research/SQL 只读类型篇或挂工具、不开独立主项目；能用 §5 指出决策、路径与交付中未完成项。</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>证协议与壳         → 配方 A</span></span>
<span class="line"><span>知识增强 + 引用    → 配方 B（叠 A）</span></span>
<span class="line"><span>业务执行 + 审批图  → 配方 C（叠 A）</span></span>
<span class="line"><span>外部 MCP 受控接入  → 配方 D（进阶）</span></span>
<span class="line"><span>证明多角色收益     → 配方 E（进阶）</span></span>
<span class="line"><span>可交接             → 决策可辩护 + 六件套齐</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div>`,73)])])}const u=s(r,[["render",i]]);export{b as __pageData,u as default};
